  1050      len = olen;
  1051      for (cp = opath, ep = opath + olen; cp < ep; cp++) {
  1052          if (cp[0] == '%' && cp[1] == 'h') {
  1053              shost_len = strlen(user_shost);
  1054              len += shost_len - 2;
  1055              subst = true;
  1056          }
  1057      }
  1058
  1059      /* Make a copy of the fully-qualified path and return it. */
  1060      path = pp = rcstr_alloc(len + dirlen);
